  {x : Fin r → R} (hI : I = Ideal.span (Set.range x)) (i : Fin r) (z : Singularity.Algebra.GrMod I M),
  Singularity.Algebra.grGen M hI i • z = (Singularity.Algebra.grShift ⋯) z

Singularity.Algebra.grMulSum_apply.type:
